    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }
}

@namespace sv_bd4aafb8c63e4558bc6654a211ea3a0d.Components.Pages.Catalog

<aside class="catalog-filters">
    <h2>Filters</h2>

    <section class="filter-section">
        <h3>Category</h3>
        @foreach (var category in Categories)
        {
            <label class="filter-checkbox">
                <input type="checkbox"
                       checked="@IsSelected(category)"
                       @onchange="@(e => ToggleCategory(category, (bool)e.Value!))" />
                @category
            </label>
        }
    </section>

    <section class="filter-section">
        <h3>Price Range</h3>
        <label>
            Min
            <input type="number" min="0" step="0.01"
                   value="@MinPrice"
                   @onchange="@(e => MinPrice = ParseDecimal(e.Value))" />
        </label>
        <label>
            Max
            <input type="number" min="0" step="0.01"
                   value="@MaxPrice"
                   @onchange="@(e => MaxPrice = ParseDecimal(e.Value))" />
        </label>
    </section>

    <section class="filter-section">
        <label class="filter-checkbox">
            <input type="checkbox"
                   checked="@InStockOnly"
                   @onchange="@(e => InStockOnly = (bool)e.Value!)" />
            In Stock Only
        </label>
    </section>

    <div class="filter-actions">
        <button class="btn-apply" @onclick="ApplyFilters">Apply Filters</button>
        <button class="btn-clear" @onclick="ClearFilters">Clear Filters</button>
    </div>
</aside>

@code {
    [Parameter, EditorRequired]
    public List<string> Categories { get; set; } = [];

    [Parameter]
    public EventCallback<ProductFilter> OnFilterApplied { get; set; }

    [Parameter]
    public EventCallback OnFilterCleared { get; set; }

    private List<string> SelectedCategories { get; set; } = [];
    private decimal? MinPrice { get; set; }
    private decimal? MaxPrice { get; set; }
    private bool InStockOnly { get; set; }

    private bool IsSelected(string category) => SelectedCategories.Contains(category);

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
        {
            if (!SelectedCategories.Contains(category))
                SelectedCategories.Add(category);
        }
        else
        {
            SelectedCategories.Remove(category);
        }
    }

    private async Task ApplyFilters()
    {
        var filter = new ProductFilter(
            Categories: SelectedCategories.Count > 0 ? new List<string>(SelectedCategories) : null,
            MinPrice: MinPrice,
            MaxPrice: MaxPrice,
            InStockOnly: InStockOnly
        );
        await OnFilterApplied.InvokeAsync(filter);
    }

    private async Task ClearFilters()
    {
        SelectedCategories.Clear();
        MinPrice = null;
        MaxPrice = null;
        InStockOnly = false;
        await OnFilterCleared.InvokeAsync();
    }

    private static decimal? ParseDecimal(object? value)
    {
        if (value is null || string.IsNullOrWhiteSpace(value.ToString()))
            return null;
        return decimal.TryParse(value.ToString(), out var result) ? result : null;
    }
}

@namespace sv_bd4aafb8c63e4558bc6654a211ea3a0d.Components.Pages.Catalog

<div class="catalog-toolbar">
    <div class="toolbar-sort">
        <label for="sort-select">Sort by:</label>
        <select id="sort-select" value="@SortBy" @onchange="HandleSortChanged">
            <option value="price_asc">Price: Low to High</option>
            <option value="price_desc">Price: High to Low</option>
            <option value="name_asc">Name: A-Z</option>
            <option value="rating_desc">Rating: Highest</option>
        </select>
    </div>
    <div class="toolbar-info">
        @if (TotalCount > 0)
        {
            <span>Showing @StartItem–@EndItem of @TotalCount products</span>
        }
    </div>
</div>

@code {
    [Parameter]
    public string SortBy { get; set; } = "price_asc";

    [Parameter]
    public int TotalCount { get; set; }

    [Parameter]
    public int Page { get; set; } = 1;

    [Parameter]
    public int PageSize { get; set; } = 12;

    [Parameter]
    public EventCallback<string> OnSortChanged { get; set; }

    private int StartItem => TotalCount == 0 ? 0 : (Page - 1) * PageSize + 1;
    private int EndItem => Math.Min(Page * PageSize, TotalCount);

    private async Task HandleSortChanged(ChangeEventArgs e)
    {
        await OnSortChanged.InvokeAsync(e.Value?.ToString() ?? "price_asc");
    }
}

@namespace sv_bd4aafb8c63e4558bc6654a211ea3a0d.Components.Pages.Catalog

<nav class="catalog-pagination" aria-label="Product pagination">
    <button class="btn-page"
            disabled="@(CurrentPage <= 1)"
            @onclick="@(() => GoToPage(CurrentPage - 1))">
        Previous
    </button>

    @for (int i = 1; i <= TotalPages; i++)
    {
        var pageNum = i;
        <button class="btn-page @(pageNum == CurrentPage ? "active" : "")"
                @onclick="@(() => GoToPage(pageNum))">
            @pageNum
        </button>
    }

    <button class="btn-page"
            disabled="@(CurrentPage >= TotalPages)"
            @onclick="@(() => GoToPage(CurrentPage + 1))">
        Next
    </button>
</nav>

@code {
    [Parameter]
    public int CurrentPage { get; set; } = 1;

    [Parameter]
    public int TotalPages { get; set; } = 1;

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private async Task GoToPage(int page)
    {
        if (page >= 1 && page <= TotalPages)
        {
            await OnPageChanged.InvokeAsync(page);
        }
    }
}

@page "/catalog"
@namespace sv_bd4aafb8c63e4558bc6654a211ea3a0d.Components.Pages.Catalog
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-layout">
    <CatalogFilters Categories="categories"
                    OnFilterApplied="HandleFilterApplied"
                    OnFilterCleared="HandleFilterCleared" />

    <main class="catalog-main">
        @if (isLoading)
        {
            <div class="catalog-loading" aria-live="polite">
                <p>Loading products...</p>
            </div>
        }
        else if (errorMessage is not null)
        {
            <div class="catalog-error" aria-live="assertive">
                <p>@errorMessage</p>
                <button @onclick="RetrySearch">Retry</button>
            </div>
        }
        else if (products.Count == 0)
        {
            <div class="catalog-empty" aria-live="polite">
                <p>No products found. Try adjusting your filters.</p>
            </div>
        }
        else
        {
            <CatalogToolbar SortBy="@sortBy"
                            TotalCount="totalCount"
                            Page="currentPage"
                            PageSize="PageSize"
                            OnSortChanged="HandleSortChanged" />

            <ProductGrid Products="products"
                         OnProductSelected="HandleProductSelected"
                         OnAddToCart="HandleAddToCart" />

            <CatalogPagination CurrentPage="currentPage"
                               TotalPages="totalPages"
                               OnPageChanged="HandlePageChanged" />
        }
    </main>
</div>

@code {
    private const int PageSize = 12;

    private List<string> categories = [];
    private List<Product> products = [];
    private int totalCount;
    private int currentPage = 1;
    private int totalPages = 1;
    private string sortBy = "price_asc";
    private ProductFilter currentFilter = new(null, null, null, false);
    private bool isLoading = true;
    private string? errorMessage;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    protected override async Task OnInitializedAsync()
    {
        await LoadCategories();
        await SearchProducts();
    }

    private async Task LoadCategories()
    {
        try
        {
            categories = await ProductService.GetCategoriesAsync();
        }
        catch
        {
            categories = [];
        }
    }

    private async Task SearchProducts()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            var result = await ProductService.SearchAsync(currentFilter, sortBy, currentPage, PageSize);
            products = result.Items;
            totalCount = result.TotalCount;
            totalPages = (int)Math.Ceiling((double)result.TotalCount / PageSize);
            if (totalPages < 1) totalPages = 1;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load products: {ex.Message}";
            products = [];
            totalCount = 0;
            totalPages = 1;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleFilterApplied(ProductFilter filter)
    {
        currentFilter = filter;
        currentPage = 1;
        await SearchProducts();
    }

    private async Task HandleFilterCleared()
    {
        currentFilter = new ProductFilter(null, null, null, false);
        currentPage = 1;
        await SearchProducts();
    }

    private async Task HandleSortChanged(string newSort)
    {
        sortBy = newSort;
        currentPage = 1;
        await SearchProducts();
    }

    private async Task HandlePageChanged(int page)
    {
        currentPage = page;
        await SearchProducts();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private async Task HandleAddToCart(Product product)
    {
        await OnAddToCart.InvokeAsync(product);
    }

    private async Task RetrySearch()
    {
        await SearchProducts();
    }
}

