+}
+
+.btn-page:hover:not(:disabled) {
+    background: #e9ecef;
+}
+
+.btn-page:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+.btn-page.active {
+    background: #0d6efd;
+    color: white;
+    border-color: #0d6efd;
+}
+
+.catalog-loading,
+.catalog-empty,
+.catalog-error {
+    text-align: center;
